export interface Figure {
  /** Stable internal id, e.g. "f1" */
  id: string;
  /** Display label, e.g. "Figure 1" */
  label: string;
  /** Figure number parsed from caption (1-based), if available */
  number: number | null;
  /** "figure" | "table" — distinguishes Figure N from Table N in the regex map */
  kind: "figure" | "table";
  caption: string;
  imageUrl: string | null;
  /** For figures that are HTML tables (no image file): the table's HTML markup */
  tableHtml?: string | null;
  /** Plain-English gloss generated by Muse Ember from caption + citing paragraphs */
  explanation?: string;
}

export interface Paragraph {
  /** Stable internal id, e.g. "p12" */
  id: string;
  /** Plain text (plain fallback, also used for regex mapping) */
  text: string;
  /** HTML with inline math markers (@@K{n}@@) and <a> links — for display */
  html: string;
  /** Raw TeX strings for each @@K{n}@@ in this paragraph, in order */
  mathTex: string[];
}

export interface ReaderData {
  arxivId: string;
  title: string;
  paragraphs: Paragraph[];
  figures: Figure[];
  /** paraId -> [figureId, ...] */
  paraFigureMap: Record<string, string[]>;
}
